package br.com.conectatea.security;
import br.com.conectatea.profissional.infrastructure.ProfissionalRepository; import br.com.conectatea.vinculo.domain.StatusVinculo; import br.com.conectatea.vinculo.infrastructure.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service;
@Service public class AuthorizationService { private final ProfissionalRepository professionals; private final VinculoProfissionalRepository pv; private final VinculoResponsavelRepository rv; public AuthorizationService(ProfissionalRepository p,VinculoProfissionalRepository pv,VinculoResponsavelRepository rv){professionals=p;this.pv=pv;this.rv=rv;} public boolean canAccessCrianca(AuthenticatedUser u,Long c){if(u.tipo()==br.com.conectatea.usuario.domain.TipoUsuario.PROFISSIONAL)return professionals.findByUsuarioId(u.id()).map(p->pv.existsByProfissionalIdAndCriancaIdAndStatus(p.getId(),c,StatusVinculo.VINCULADO)).orElse(false);return rv.existsByResponsavelIdAndCriancaIdAndStatus(u.id(),c,StatusVinculo.VINCULADO);} public void requireCrianca(AuthenticatedUser u,Long c){if(!canAccessCrianca(u,c))throw new AccessDeniedException("Sem vínculo ativo com a criança");} }

